import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.assigners.TumblingEventTimeWindows;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import java.time.Duration;

StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

DataStream<PageView> pageViews = env
    .fromSource(kafkaSource, WatermarkStrategy
        .<PageView>forBoundedOutOfOrderness(Duration.ofMinutes(2))
        .withTimestampAssigner((view, ts) -> view.eventTimestamp),
        "kafka-page-views")
    .name("page-view-source");

DataStream<UrlCount> counts = pageViews
    .keyBy(view -> view.url)
    .window(TumblingEventTimeWindows.of(Time.minutes(5)))
    .aggregate(new CountAggregate())
    .name("five-min-tumbling-count");

counts.print();
env.execute("page-view-window-count");

