KStream<String, PageView> pageViews = builder.stream("page-views");

KTable<Windowed<String>, Long> counts = pageViews
    .groupBy((key, view) -> view.getUrl())
    .windowedBy(TimeWindows.ofSizeAndGrace(
        Duration.ofMinutes(5),   // window size
        Duration.ofMinutes(2)))  // grace period for late events
    .count();

counts.toStream().foreach((windowedUrl, count) ->
    System.out.println(windowedUrl.key() + " -> " + count));

